// FEE AND INTEREST AUDIT — what the accounts are charging, gathered into one place.
//
// Fees are invisible for a structural reason: each one is small and they are scattered across months
// and accounts. Nobody adds them up, so nobody sees the total, so nobody acts. Listing them together
// turns a statement into a call sheet — many are reversible on request, and a repeating fee is
// usually a standing condition (a plan, a threshold, a due date) that can be changed once.
//
// PATTERNS ARE DATA. Institutions word these differently and change the wording; a matcher hard-coded
// into the logic would silently stop matching and report a clean bill of health, which is the worst
// possible failure for an audit. So the patterns are a table, correctable in one line, and anything
// that looks fee-shaped but matches nothing is REPORTED as unclassified rather than dropped.
import { type Money, money, sum, format } from "@/features/finance/lib/money";
import { type Txn, monthOf } from "@/features/finance/lib/txn";

/** What kind of charge this is. The kinds differ in what you can do about them, which is the point. */
export type FeeKind =
  | "interest"
  | "late"
  | "overdraft"
  | "nsf"
  | "annual"
  | "foreign-transaction"
  | "cash-advance"
  | "service"
  | "other";

export interface FeePattern {
  readonly kind: FeeKind;
  /** Matched case-insensitively against the description. */
  readonly match: RegExp;
  /** What a person can usually do about this kind — stated so the report is actionable rather than
   *  merely accurate. Never a promise: an issuer decides, not this table. */
  readonly lever: string;
}

/**
 * The patterns, as data.
 *
 * Written from common US card and checking wording. They SHOULD be corrected against real statements
 * — an audit that quietly matches nothing reports zero fees, which reads exactly like good news.
 */
export const FEE_PATTERNS: readonly FeePattern[] = [
  { kind: "interest", match: /interest charge|finance charge|purchase interest|int chg/i,
    lever: "a rate reduction, or clearing the balance faster — this is the recurring cost of the balance itself" },
  { kind: "late", match: /late fee|late charge|past due fee/i,
    lever: "usually reversible on request, especially once; a due-date change prevents the next one" },
  { kind: "overdraft", match: /overdraft|od fee|odp fee/i,
    lever: "often reversible; overdraft coverage can be switched off, or a buffer account linked" },
  { kind: "nsf", match: /nsf|non.?sufficient|returned item|insufficient funds/i,
    lever: "often reversible once; the underlying cause is timing rather than total" },
  { kind: "annual", match: /annual fee|membership fee|card fee/i,
    lever: "ask for it to be waived, or move to a no-fee product on the same account" },
  { kind: "foreign-transaction", match: /foreign transaction|foreign purchase|intl? fee/i,
    lever: "structural — a no-foreign-fee card avoids it entirely" },
  { kind: "cash-advance", match: /cash advance|cash adv fee/i,
    lever: "no grace period and a higher rate; the fix is not using the facility" },
  { kind: "service", match: /service charge|maintenance fee|monthly fee|paper statement/i,
    lever: "usually waived by a balance minimum, a direct deposit, or switching statement delivery" },
];

export interface Fee {
  readonly date: string;
  readonly account: string;
  readonly description: string;
  readonly amount: Money;
  readonly kind: FeeKind;
  readonly lever: string;
}

export interface FeeAudit {
  readonly fees: readonly Fee[];
  /** Total charged over the whole set. The number nobody has ever seen before running this. */
  readonly total: Money;
  readonly byKind: ReadonlyMap<FeeKind, Money>;
  readonly byAccount: ReadonlyMap<string, Money>;
  /** A kind that appears in three or more distinct months on one account: not an accident, a standing
   *  condition. These are where a single change stops a stream of charges. */
  readonly recurringConditions: readonly { account: string; kind: FeeKind; months: number; total: Money; lever: string }[];
  /** Looked fee-shaped, matched no pattern. REPORTED so a gap in the table is visible as a gap — an
   *  audit that silently matches nothing reports zero fees, which reads like good news. */
  readonly unclassified: readonly Txn[];
}

/** Words that mark a line as fee-shaped even when no specific pattern matches it. */
const FEE_SHAPED = /\bfee\b|\bcharge\b|\binterest\b|\bpenalty\b/i;

export function auditFees(txns: readonly Txn[], currency: string): FeeAudit {
  const fees: Fee[] = [];
  const unclassified: Txn[] = [];

  for (const t of txns) {
    // A fee is money leaving. A line matching "interest" that pays IN is interest earned, which is a
    // different thing entirely and must not be totalled as a cost.
    if (t.amount.minor >= 0) continue;
    const pattern = FEE_PATTERNS.find((p) => p.match.test(t.description));
    if (pattern) {
      fees.push({
        date: t.date,
        account: t.account,
        description: t.description,
        amount: t.amount,
        kind: pattern.kind,
        lever: pattern.lever,
      });
    } else if (FEE_SHAPED.test(t.description)) {
      unclassified.push(t);
    }
  }

  const byKind = new Map<FeeKind, Money>();
  const byAccount = new Map<string, Money>();
  for (const f of fees) {
    byKind.set(f.kind, money((byKind.get(f.kind)?.minor ?? 0) + f.amount.minor, currency));
    byAccount.set(f.account, money((byAccount.get(f.account)?.minor ?? 0) + f.amount.minor, currency));
  }

  // A REPEATING fee is the finding worth acting on: one change stops the whole stream.
  const months = new Map<string, Set<string>>();
  const totals = new Map<string, Money>();
  const levers = new Map<string, string>();
  for (const f of fees) {
    const id = `${f.account}�${f.kind}`;
    const set = months.get(id) ?? months.set(id, new Set()).get(id)!;
    set.add(monthOf(f.date));
    totals.set(id, money((totals.get(id)?.minor ?? 0) + f.amount.minor, currency));
    levers.set(id, f.lever);
  }
  const recurringConditions = [...months.entries()]
    .filter(([, m]) => m.size >= 3)
    .map(([id, m]) => {
      const [account, kind] = id.split("�");
      return { account, kind: kind as FeeKind, months: m.size, total: totals.get(id)!, lever: levers.get(id)! };
    })
    // Costliest standing condition first — that is the one to change.
    .sort((a, b) => a.total.minor - b.total.minor);

  return {
    fees,
    total: sum(fees.map((f) => f.amount), currency),
    byKind,
    byAccount,
    recurringConditions,
    unclassified,
  };
}

/** A one-line summary a person can read without opening the detail. */
export const summarise = (a: FeeAudit): string =>
  `${a.fees.length} charge(s) totalling ${format(a.total)}` +
  (a.recurringConditions.length ? `, ${a.recurringConditions.length} recurring condition(s)` : "") +
  (a.unclassified.length ? `, ${a.unclassified.length} unclassified` : "");

