import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import { auditFees, summarise, FEE_PATTERNS } from "@/features/finance/lib/fees";
import type { Txn } from "@/features/finance/lib/txn";

// SYNTHETIC FIXTURES ONLY.
const usd = (major: number): Money => fromMajor(major, "USD");
const t = (date: string, description: string, major: number, account = "card"): Txn => ({
  date,
  description,
  amount: usd(-Math.abs(major)),
  account,
});

describe("auditFees — gathering what is scattered", () => {
  it("finds each kind and totals them", () => {
    // Individually small, spread over months, invisible. Together they are a call sheet.
    const rows = [
      t("2026-01-15", "INTEREST CHARGE ON PURCHASES", 42.11),
      t("2026-02-02", "LATE FEE", 39.0),
      t("2026-02-15", "INTEREST CHARGE ON PURCHASES", 44.9),
      t("2026-03-01", "FOREIGN TRANSACTION FEE", 2.4),
      t("2026-03-09", "GROCERY STORE", 88.12),
    ];
    const a = auditFees(rows, "USD");
    expect(a.fees).toHaveLength(4);
    expect(a.total.minor).toBe(-(4211 + 3900 + 4490 + 240));
    expect(a.byKind.get("interest")!.minor).toBe(-(4211 + 4490));
    expect(a.byKind.get("late")!.minor).toBe(-3900);
  });

  it("carries a LEVER, so the report is actionable and not merely accurate", () => {
    const a = auditFees([t("2026-02-02", "LATE FEE", 39)], "USD");
    expect(a.fees[0].lever).toMatch(/reversible/i);
    // But never a promise — an issuer decides, not this table.
    expect(a.fees[0].lever).not.toMatch(/will be|guaranteed/i);
  });

  it("does NOT count interest EARNED as a cost", () => {
    // A line matching "interest" that pays IN is a different thing entirely, and totalling it as a
    // cost would make a savings account look like a problem.
    const earned: Txn = { date: "2026-01-31", description: "INTEREST PAID", amount: usd(1.22), account: "savings" };
    expect(auditFees([earned], "USD").fees).toEqual([]);
  });
});

describe("auditFees — the standing condition", () => {
  it("flags a fee repeating across THREE months as a condition, not an accident", () => {
    // This is the finding worth acting on: one change stops the whole stream.
    const rows = ["2026-01-05", "2026-02-05", "2026-03-05", "2026-04-05"].map((d) =>
      t(d, "MONTHLY MAINTENANCE FEE", 12, "checking"),
    );
    const a = auditFees(rows, "USD");
    expect(a.recurringConditions).toHaveLength(1);
    expect(a.recurringConditions[0]).toMatchObject({ account: "checking", kind: "service", months: 4 });
    expect(a.recurringConditions[0].total.minor).toBe(-4800);
  });

  it("does not call two occurrences a standing condition", () => {
    const rows = ["2026-01-05", "2026-02-05"].map((d) => t(d, "LATE FEE", 39));
    expect(auditFees(rows, "USD").recurringConditions).toEqual([]);
  });

  it("counts MONTHS, not occurrences — three in one month is one bad month", () => {
    const rows = ["2026-01-05", "2026-01-15", "2026-01-25"].map((d) => t(d, "OVERDRAFT FEE", 35, "checking"));
    expect(auditFees(rows, "USD").recurringConditions).toEqual([]);
  });
});

describe("auditFees — an audit must not report a clean bill by accident", () => {
  it("REPORTS a fee-shaped line it could not classify", () => {
    // Institutions reword these and a hard-coded matcher silently stops matching. Zero fees reads
    // exactly like good news, which is the worst possible failure for an audit.
    const odd = t("2026-05-01", "RELATIONSHIP CHARGE ASSESSMENT", 9.5);
    const a = auditFees([odd], "USD");
    expect(a.fees).toEqual([]);
    expect(a.unclassified).toHaveLength(1);
    expect(summarise(a)).toMatch(/unclassified/);
  });

  it("does not treat ordinary spending as fee-shaped", () => {
    const a = auditFees([t("2026-05-01", "GROCERY STORE", 54.2), t("2026-05-02", "GAS STATION", 41.0)], "USD");
    expect(a.fees).toEqual([]);
    expect(a.unclassified).toEqual([]);
  });

  it("every pattern is reachable and none shadows another", () => {
    // A pattern nothing can select is dead configuration that reads as coverage — the same shape as
    // an unreachable statement profile.
    const sample: Record<string, string> = {
      interest: "INTEREST CHARGE ON PURCHASES",
      late: "LATE FEE",
      overdraft: "OVERDRAFT FEE",
      nsf: "NSF RETURNED ITEM",
      annual: "ANNUAL FEE",
      "foreign-transaction": "FOREIGN TRANSACTION FEE",
      "cash-advance": "CASH ADVANCE FEE",
      service: "MONTHLY MAINTENANCE FEE",
    };
    for (const p of FEE_PATTERNS) {
      const text = sample[p.kind];
      expect(text, `no sample for ${p.kind}`).toBeDefined();
      const first = FEE_PATTERNS.find((q) => q.match.test(text));
      expect(first!.kind, `${p.kind} is shadowed by ${first!.kind}`).toBe(p.kind);
    }
  });
});
